//variables and datatypes
//Programmer: James Goudy

//import this if you want to use stdout and stdin
import 'dart:io';

void variableReview() {
  /*
  variables
  note if initial values are not declared
  then the intial value is null

  ALL VARIABLES ARE OBJECTS
  */

  print('Variable Review\n');
  //numbers
  double salary = 0.0;
  int anum = 42;

  //Note that salary is an object so the .toString() function is called
  print('double  = ' + salary.toString() + "\n");
  print('int = ' + anum.toString() + '\n');

  //String and booleans
  //note you can use both single or double quotes
  String someWord = 'This is a string';
  String someWord2 = "Yada Yada";
  bool isBreathing = true;

  print("\n Print string variable someWord:  " + someWord);

  //note a dollar sign in front of variable name
  //the dollar sign makes it a place holder in a string 
  //when attached to a variable.
  print('\n Print string variable someWord2: $someWord2');
  print("\n Print boolean variable isBreathing: " + isBreathing.toString());

  //lists / arrays - orderd list
  var nums = [10, 20, 30, 40, 50];
  var names = ["Larry", "Curly", "Moe", "Shemp"];

  print("\nPrint nums list using a for statement");
  for (int c = 0; c &lt; nums.length; c++) {
    //import dart.io
    stdout.write(nums[c].toString() + " ");
  }

  //using a string
  String theString = " ";

  print("\n\nPrint nums list by concatenating a variable");
  for (int c = 0; c &lt; nums.length; c++) {
    theString = theString + nums[c].toString() + " ";
  }
  print(theString);

  print("\nPrint nums list by using an anonymous function");
  nums.forEach((numsIndex) {
    stdout.write(nums.indexOf(numsIndex).toString() + " ");
  } //end of anonymous function
      ); //end of forEach function

  print("\nPrint String List of Names");
  names.forEach((stooge) =&gt; stdout.write(stooge + " "));

  //sets -  unordered collection of ** UNIQUE ** items
  var us_states = {'MT', 'OH', 'NV', 'WY', 'CO'};

  //print set
  print("\n\n Print set");
  for (var value in us_states) {
    stdout.write(value + " ");
  }
  int cs = 1;
  print('\nIndividual element at position 1 = ' + us_states.elementAt(cs));

  //maps - key : value
  var vehicles = {
    'car': 'mustang',
    'airplane': 'cessna',
    'boat': 'wellcraft',
    'truck': 'f150',
    'scooter': 'lime',
    'personal': 'segway'
  };

  print('\nPrint keys in Maps');
  for (var valueKey in vehicles.keys) {
    stdout.write(valueKey + " ");
  }

  print('\n\nPrint keys in Maps');
  for (var value in vehicles.values) {
    stdout.write(value + " ");
  }

  print("\n\nKey Value Pairs in Maps");
  vehicles.forEach((k, v) =&gt; stdout.writeln('Key=$k, Value=$v'));

  print('\n print value for the specific key of "truck"');
  print(vehicles['truck']);

  //Runes - emoji
  var personalComputer = '\u{1F4BB}';
  var camera = '\u{1F4F7}';

  print('\nPrint Runes');
  print(personalComputer + " " + camera);

  //generic var datatype - Dart will interpret the data type
  var num1 = 80;
  var num2 = 20;
  var unit = "miles";
  print("\nVar example");
  print("var add num1 + num2 = " + (num1 + num2).toString() + " $unit");

  //dynamic dataype the data type can change
  dynamic xx = "Some text"; //string
  xx = 42.0; //double
  xx = true; //boolean
  xx = '\u{1F603}'; //rune
  print("\nxx is equal to $xx\n");
}

main(List&lt;String&gt; arguments) {
  variableReview();

  print("\n\nGoody Bye");
}

Lambda functions







NoteDefinition



Lambda Function is an anonymous function that can take arguments, but only has one expression / only one formula.




Lambda Functions: The code demonstrates the use of lambda functions, which are concise anonymous functions often used for inline expressions.
List/Array: It creates a list of numbers and performs various operations on it.
Function Calls: Functions are called to print the numbers and calculate their sum.
Output: The program prints the numbers, their sum using both traditional and lambda functions, and a final “Bye bye” message.



Lambda Function Definition:

num Sum3Lambda(num xx, yy, zz) =&gt; (xx + yy + zz); defines a lambda function that takes three numbers as input and returns their sum. The arrow (=&gt;) syntax is used to concisely define the function body.

Traditional Function Definition:

void printNums(var alist) { ... } defines a traditional function that takes a list as input and prints its elements using a for loop.

Main Function:

The main function is the entry point of the program.
It creates a list of numbers.
Calls the printNums function to print the numbers using a traditional function.
Uses the forEach method with a lambda function to print the numbers concisely.
Calculates and prints the sum of the first three numbers using both Sum3 and Sum3Lambda functions.
Prints a final “Bye bye” message.


import 'dart:io';

//in Dart, if you can write a function in one line
//then it can be written as a lambda function.

//traditional form of a function
void printNums(var alist) {
  for (var item in alist) {
    stdout.write(item.toString() + " ");
  }
}

//Sum 3 numbers
num Sum3(num xx, num yy, num zz) {
  num ans = 0;

  ans = xx + yy + zz;

  return ans;
}

//Sum 3 numbers written as a Lambda Function
num Sum3Lambda(num xx, yy, zz) =&gt; (xx + yy + zz);

main(List&lt;String&gt; arguments) {

  //List / array
  var someNums = [10, 20, 80, 77, 26, 79, 37, 58, 8, 98, 2, 23, 54, 81, 3];

  //print numbers
  print("Print Numbers using function");

  //call function and pass the array
  printNums(someNums);

  //print numbers
  print("\n\nPrint Numbers using a lambda function");
  someNums.forEach((var item) =&gt; stdout.write(item.toString() + " "));

  print("\n\Sum 3 numbers ");
  stdout.writeln(Sum3(someNums[0], someNums[1], someNums[2]));

  print("\n\Sum 3 numbers using a lambda function");
  stdout.writeln(Sum3Lambda(someNums[0], someNums[1], someNums[2]));

  print("\nBye bye");
}

