  theDate() async {
    _date = (await showDatePicker(
        context: context,
        initialDate: DateTime.now(),
        firstDate: DateTime(2000, 1, 1),
        lastDate: DateTime(3000, 1, 1)))!;

    // Updates the displayed date in 'myDate1' after selection
    setState(() {
      if (_date.toString() != "") {
        myDate1 = "${_date.month} / ${_date.day} / ${_date.year}";
      } else {
        myDate1 = "";
      }
    });
  }

