class GameScreen extends StatefulWidget {
  @override
  _GameScreenState createState() =&gt; _GameScreenState();
}

class _GameScreenState extends State&lt;GameScreen&gt; {
  // Ball position and speed
  double ballX = 0.0;
  double ballY = 0.0;
  double ballSpeedX = 0.02;
  double ballSpeedY = 0.02;

  // Paddle position
  double paddleX = 0.0;
  double paddleWidth = 0.4;

  // Brick variables
  int numRows = 3;
  int numCols = 5;
  List&lt;List&lt;bool&gt;&gt; bricks = [];

  @override
  void initState() {
    super.initState();
    _initializeBricks();
    _startGame();
  }

  void _initializeBricks() {
    for (int i = 0; i &lt; numRows; i++) {
      bricks.add(List.filled(numCols, true));
    }
  }

  void _startGame() {
    Timer.periodic(Duration(milliseconds: 30), (timer) {
      setState(() {
        _moveBall();
      });
    });
  }

  void _moveBall() {
    ballX += ballSpeedX;
    ballY += ballSpeedY;

    // Ball collision with walls
    if (ballX &lt;= -1 || ballX &gt;= 1) ballSpeedX = -ballSpeedX;
    if (ballY &lt;= -1) ballSpeedY = -ballSpeedY;

    // Ball collision with paddle
    if (ballY &gt;= 0.9 &&
        ballX &gt;= paddleX - paddleWidth / 2 &&
        ballX &lt;= paddleX + paddleWidth / 2) {
      ballSpeedY = -ballSpeedY;
    }

    // Ball collision with bricks
    for (int i = 0; i &lt; numRows; i++) {
      for (int j = 0; j &lt; numCols; j++) {
        if (bricks[i][j]) {
          double brickTop = -0.8 + i * 0.2;
          double brickLeft = -1 + j * 0.4;
          double brickRight = brickLeft + 0.4;

          if (ballY &gt;= brickTop &&
              ballY &lt;= brickTop + 0.1 &&
              ballX &gt;= brickLeft &&
              ballX &lt;= brickRight) {
            bricks[i][j] = false;
            ballSpeedY = -ballSpeedY;
          }
        }
      }
    }

    // Ball out of bounds (Game Over)
    if (ballY &gt;= 1) {
      _resetGame();
    }
  }

  void _resetGame() {
    ballX = 0.0;
    ballY = 0.0;
    ballSpeedX = 0.02;
    ballSpeedY = 0.02;
    paddleX = 0.0;
    bricks.clear();
    _initializeBricks();
  }

  void _movePaddle(DragUpdateDetails details) {
    setState(() {
      paddleX += details.delta.dx / MediaQuery.of(context).size.width * 2;
      paddleX = paddleX.clamp(-1 + paddleWidth / 2, 1 - paddleWidth / 2);
    });
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onHorizontalDragUpdate: _movePaddle,
      child: Stack(
        children: [
          // Ball
          Align(
            alignment: Alignment(ballX, ballY),
            child: Container(
              width: 20,
              height: 20,
              decoration: BoxDecoration(
                color: Colors.white,
                shape: BoxShape.circle,
              ),
            ),
          ),
          // Paddle
          Align(
            alignment: Alignment(paddleX, 0.95),
            child: Container(
              width: MediaQuery.of(context).size.width * paddleWidth,
              height: 20,
              color: Colors.blue,
            ),
          ),
          // Bricks
          for (int i = 0; i &lt; numRows; i++)
            for (int j = 0; j &lt; numCols; j++)
              if (bricks[i][j])
                Align(
                  alignment: Alignment(-1 + j * 0.4 + 0.2, -0.8 + i * 0.2),
                  child: Container(
                    width: MediaQuery.of(context).size.width * 0.2,
                    height: 40,
                    color: Colors.red,
                  ),
                ),
        ],
      ),
    );
  }
}

5. Camera integration and image storage
Flutter provides several approaches to camera integration. The camera package offers direct control over camera previews and capture sessions, but requires additional lifecycle and controller management. For an application that simply needs to acquire a photograph, image_picker is a simpler choice.
The form calls the same method with either ImageSource.camera or ImageSource.gallery. If the user cancels the picker, the returned value is null and the existing photo remains unchanged.
Camera captures may reside in temporary cache storage. Saving a temporary path to the database does not ensure that the photograph will remain available. The application therefore copies the selected file into its application documents directory before recording its path.
final appDir = await getApplicationDocumentsDirectory();
final fileName = 'pet_${DateTime.now().millisecondsSinceEpoch}${p.extension(pickedFile.path)}';
final permanentPath = p.join(appDir.path, fileName);
final savedImage = await File(pickedFile.path).copy(permanentPath);
The timestamp helps distinguish file names, although it is not a strict uniqueness guarantee. The picker requests a maximum width of 1000 pixels and an image quality of 85 to reduce storage and decoding costs where supported. Application documents storage persists across ordinary restarts, but it is not a backup and may be removed when application data is cleared or the app is uninstalled.

