Build the settings application
The application has three editable settings, a name-saving button, a restore-defaults button, and a live preview. The theme and text-size selections save as they change. The name saves when you press Save Name.
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() {
  runApp(const SettingsDemoApp());
}

class SettingsDemoApp extends StatefulWidget {
  const SettingsDemoApp({super.key});

  @override
  State&lt;SettingsDemoApp&gt; createState() =&gt; _SettingsDemoAppState();
}

class _SettingsDemoAppState extends State&lt;SettingsDemoApp&gt; {
  // Keys are constant names for values stored on the device.
  static const String nameKey = 'display_name';
  static const String darkModeKey = 'dark_mode';
  static const String fontSizeKey = 'font_size';

  // Current recommended asynchronous preferences API.
  final SharedPreferencesAsync _prefs = SharedPreferencesAsync();

  // Controller for the editable display name.
  final TextEditingController _nameController = TextEditingController();

  // Allows this root widget to show a SnackBar from its methods.
  final GlobalKey&lt;ScaffoldMessengerState&gt; _messengerKey =
      GlobalKey&lt;ScaffoldMessengerState&gt;();

  bool _loading = true;
  bool _darkMode = false;
  double _fontSize = 18.0;
  String _savedName = '';

  @override
  void initState() {
    super.initState();
    _loadSettings();
  }

  // Read the settings when the application starts.
  Future&lt;void&gt; _loadSettings() async {
    try {
      final String name = await _prefs.getString(nameKey) ?? '';
      final bool dark = await _prefs.getBool(darkModeKey) ?? false;
      final double size = await _prefs.getDouble(fontSizeKey) ?? 18.0;

      if (!mounted) return;
      _nameController.text = name;
      setState(() {
        _savedName = name;
        _darkMode = dark;
        _fontSize = size.clamp(14.0, 30.0).toDouble();
        _loading = false;
      });
    } catch (error) {
      if (!mounted) return;
      setState(() =&gt; _loading = false);
      _showMessage('Could not load settings: $error');
    }
  }

  void _showMessage(String message) {
    _messengerKey.currentState
      ?..hideCurrentSnackBar()
      ..showSnackBar(SnackBar(content: Text(message)));
  }

  // Save the display name when the Save Name button is pressed.
  Future&lt;void&gt; _saveName() async {
    final String name = _nameController.text.trim();
    try {
      await _prefs.setString(nameKey, name);
      if (!mounted) return;
      setState(() =&gt; _savedName = name);
      _showMessage('Name saved.');
    } catch (error) {
      if (mounted) _showMessage('Could not save name: $error');
    }
  }

  // Update the theme immediately, then save the choice.
  Future&lt;void&gt; _changeDarkMode(bool enabled) async {
    setState(() =&gt; _darkMode = enabled);
    try {
      await _prefs.setBool(darkModeKey, enabled);
    } catch (error) {
      if (mounted) _showMessage('Could not save dark mode: $error');
    }
  }

  // Slider dragging updates the preview; releasing saves once.
  Future&lt;void&gt; _saveFontSize(double size) async {
    try {
      await _prefs.setDouble(fontSizeKey, size);
    } catch (error) {
      if (mounted) _showMessage('Could not save font size: $error');
    }
  }

  // Remove only the preferences owned by this demonstration.
  Future&lt;void&gt; _restoreDefaults() async {
    try {
      await _prefs.remove(nameKey);
      await _prefs.remove(darkModeKey);
      await _prefs.remove(fontSizeKey);

      if (!mounted) return;
      _nameController.clear();
      setState(() {
        _savedName = '';
        _darkMode = false;
        _fontSize = 18.0;
      });
      _showMessage('Default settings restored.');
    } catch (error) {
      if (mounted) _showMessage('Could not reset settings: $error');
    }
  }

  @override
  void dispose() {
    _nameController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Persistent Settings Demo',
      debugShowCheckedModeBanner: false,
      scaffoldMessengerKey: _messengerKey,
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.indigo),
        useMaterial3: true,
      ),
      darkTheme: ThemeData(
        colorScheme: ColorScheme.fromSeed(
          seedColor: Colors.indigo,
          brightness: Brightness.dark,
        ),
        useMaterial3: true,
      ),
      themeMode: _darkMode ? ThemeMode.dark : ThemeMode.light,
      home: Scaffold(
        appBar: AppBar(title: const Text('Persistent Settings')),
        body: _loading
            ? const Center(child: CircularProgressIndicator())
            : SafeArea(
                child: ListView(
                  padding: const EdgeInsets.all(20),
                  children: [
                    const Text(
                      'Change these settings, close the app, '
                      'and open it again.',
                    ),
                    const SizedBox(height: 24),

                    // Setting #1: String
                    TextField(
                      controller: _nameController,
                      decoration: const InputDecoration(
                        labelText: 'Display name',
                        hintText: 'Enter your name',
                        border: OutlineInputBorder(),
                      ),
                      textInputAction: TextInputAction.done,
                      onSubmitted: (_) =&gt; _saveName(),
                    ),
                    const SizedBox(height: 8),
                    ElevatedButton.icon(
                      onPressed: _saveName,
                      icon: const Icon(Icons.save),
                      label: const Text('Save Name'),
                    ),
                    const SizedBox(height: 12),
                    const Divider(),

                    // Setting #2: bool
                    SwitchListTile(
                      title: const Text('Dark mode'),
                      subtitle: const Text('Remember the theme'),
                      value: _darkMode,
                      onChanged: _changeDarkMode,
                    ),
                    const Divider(),

                    // Setting #3: double
                    Text('Preview font size: ${_fontSize.round()}'),
                    Slider(
                      min: 14.0,
                      max: 30.0,
                      divisions: 16,
                      label: _fontSize.round().toString(),
                      value: _fontSize,
                      onChanged: (double value) {
                        setState(() =&gt; _fontSize = value);
                      },
                      onChangeEnd: _saveFontSize,
                    ),
                    const Divider(),
                    const SizedBox(height: 16),

                    // Live preview using the saved name and settings.
                    Text(
                      _savedName.isEmpty
                          ? 'Welcome, student!'
                          : 'Welcome, $_savedName!',
                      style: TextStyle(
                        fontSize: _fontSize,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    const SizedBox(height: 24),
                    OutlinedButton.icon(
                      onPressed: _restoreDefaults,
                      icon: const Icon(Icons.restart_alt),
                      label: const Text('Restore Defaults'),
                    ),
                  ],
                ),
              ),
      ),
    );
  }
}

Understanding the code
A. The three keys. display_name, dark_mode, and font_size are strings identifying values in device storage. Their exact spelling matters when we read them back. The constant names help avoid typographical errors.
B. The preferences object. final SharedPreferencesAsync _prefs = SharedPreferencesAsync(); creates an interface to asynchronous key-value storage. Unlike the legacy API, we do not call SharedPreferences.getInstance().
C. Starting the load. initState() runs once when the state object is created. It calls _loadSettings(), which reads the saved values. While those reads are underway, the application displays a CircularProgressIndicator.
D. Default values and null. A fresh installation has no saved values. The ?? operator supplies '', false, and 18.0 when a key is absent. The font size is also clamped to the allowed slider range in case stored data is outside that range.
E. Updating the screen versus saving. setState() changes Flutter’s in-memory state and triggers a rebuild. _prefs.setBool(), _prefs.setDouble(), and _prefs.setString() request writes to persistent storage. They do different jobs. The switch both updates the interface and saves its new value.
F. Text input. TextEditingController manages the text field. We use .text.trim() to read the entered name and call .dispose() when the state is destroyed. Unlike the switch, the name is saved only when you press Save Name or submit the field.
G. Slider behavior. onChanged changes the preview immediately as the slider moves. onChangeEnd saves once when the drag ends, avoiding a write on every movement.
H. Removing values. The Restore Defaults button uses remove() for our three keys and restores the starting UI values. Removing only known keys is safer than clearing every preference in a larger app.
I. Asynchrony and errors. Every storage read or write uses await. The try/catch blocks provide basic error messages, and mounted prevents calls to setState() after a widget has been disposed of.

Advanced note, optional reading: Rapid overlapping writes or reset operations can require additional coordination in a production app. For this small demonstration, wait for one operation to finish before testing another. In a larger app, centralize settings management and serialize conflicting writes.

/*
  Sqflite Cars Teaching App
  --------------------------
  This app demonstrates CRUD operations (Create, Read, Update, Delete)
  using the Sqflite package in Flutter.

  Students learn:
  - How to integrate a local SQLite database using Sqflite.
  - How to build a form to insert new data.
  - How to display data in a ListView.
  - How to edit and delete records dynamically.
*/

import 'package:flutter/material.dart';
import 'package:path/path.dart' as p;
import 'package:path_provider/path_provider.dart';
import 'package:sqflite/sqflite.dart';

// -----------------------------
// Main entry point
// -----------------------------
Future&lt;void&gt; main() async {
  WidgetsFlutterBinding.ensureInitialized(); // Required before async DB init
  await CarDatabase.instance.database;        // Initialize database
  runApp(const CarApp());
}

// -----------------------------
// Root of the app
// -----------------------------
class CarApp extends StatelessWidget {
  const CarApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Sqflite Car Demo',
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue),
        useMaterial3: true,
      ),
      home: const CarHomePage(), // Main screen widget
    );
  }
}

// -----------------------------
// Main screen widget
// -----------------------------
class CarHomePage extends StatefulWidget {
  const CarHomePage({super.key});

  @override
  State&lt;CarHomePage&gt; createState() =&gt; _CarHomePageState();
}

class _CarHomePageState extends State&lt;CarHomePage&gt; {
  // Text controllers for form input fields
  final _makeController = TextEditingController();
  final _modelController = TextEditingController();
  final _yearController = TextEditingController();
  final _colorController = TextEditingController();

  // List to hold all car records
  List&lt;Car&gt; _cars = &lt;Car&gt;[];

  @override
  void initState() {
    super.initState();
    _refreshCars(); // Load cars from database when app starts
  }

  // Dispose controllers to avoid memory leaks
  @override
  void dispose() {
    _makeController.dispose();
    _modelController.dispose();
    _yearController.dispose();
    _colorController.dispose();
    super.dispose();
  }

  // -----------------------------
  // Helper functions
  // -----------------------------

  // Reloads car list from database
  Future&lt;void&gt; _refreshCars() async {
    final cars = await CarDatabase.instance.fetchCars();
    setState(() {
      _cars = cars;
    });
  }

  // Adds a new car to the database
  Future&lt;void&gt; _addCar() async {
    final make = _makeController.text.trim();
    final model = _modelController.text.trim();
    final color = _colorController.text.trim();
    final year = int.tryParse(_yearController.text.trim());

    // Basic validation
    if (make.isEmpty || model.isEmpty || color.isEmpty || year == null) {
      _showSnackBar('Please provide make, model, year, and color.');
      return;
    }

    await CarDatabase.instance.insertCar(
      Car(make: make, model: model, year: year, color: color),
    );

    // Clear form fields and reload list
    _makeController.clear();
    _modelController.clear();
    _yearController.clear();
    _colorController.clear();

    await _refreshCars();
    _showSnackBar('Car added successfully.');
  }

  // Deletes a car from database
  Future&lt;void&gt; _deleteCar(Car car) async {
    await CarDatabase.instance.deleteCar(car.id!);
    await _refreshCars();
    _showSnackBar('Deleted ${car.displayName}.');
  }

  // Edits an existing car record (opens dialog)
  Future&lt;void&gt; _editCar(Car car) async {
    final edited = await showDialog&lt;Car?&gt;(
      context: context,
      builder: (context) {
        // Prefill text fields with current car data
        final makeController = TextEditingController(text: car.make);
        final modelController = TextEditingController(text: car.model);
        final yearController = TextEditingController(text: car.year.toString());
        final colorController = TextEditingController(text: car.color);

        return AlertDialog(
          title: const Text('Edit Car'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(controller: makeController, 
                          decoration: const InputDecoration(labelText: 'Make')),
                TextField(controller: modelController, 
                          decoration: const InputDecoration(labelText: 'Model')),
                TextField(controller: yearController, 
                          decoration: const InputDecoration(labelText: 'Year'),
                          keyboardType: TextInputType.number),
                TextField(controller: colorController, 
                          decoration: const InputDecoration(labelText: 'Color')),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () =&gt; Navigator.of(context).pop(),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () {
                final make = makeController.text.trim();
                final model = modelController.text.trim();
                final color = colorController.text.trim();
                final year = int.tryParse(yearController.text.trim());

                // Validate edited input
                if (make.isEmpty || model.isEmpty || color.isEmpty || year == null) {
                  Navigator.of(context).pop();
                  _showSnackBar('Invalid input for edit.');
                  return;
                }

                // Create updated car
                final updated = car.copyWith(make: make, model: model, year: year, color: color);
                Navigator.of(context).pop(updated);
              },
              child: const Text('Save'),
            ),
          ],
        );
      },
    );

    // If edited data returned, update database
    if (edited != null) {
      await CarDatabase.instance.updateCar(edited);
      await _refreshCars();
      _showSnackBar('Updated ${edited.displayName}.');
    }
  }

  // Displays a snackbar message
  void _showSnackBar(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
  }

  // -----------------------------
  // Build UI
  // -----------------------------
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Sqflite Cars Teaching App'),
        backgroundColor: Colors.green,
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            // Form card for adding new cars
            Card(
              elevation: 4,
              child: Padding(
                padding: const EdgeInsets.all(16.0),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const Text('Add a Car', style: TextStyle(fontSize: 18, 
                                                             fontWeight: ontWeight.bold)),
                    const SizedBox(height: 12),
                    TextField(controller: _makeController, 
                              decoration: const InputDecoration(labelText: 'Make')),
                    TextField(controller: _modelController, 
                              decoration: const InputDecoration(labelText: 'Model')),
                    TextField(controller: _yearController, 
                              decoration: const InputDecoration(labelText: 'Year'),
                              keyboardType: TextInputType.number),
                    TextField(controller: _colorController, 
                              decoration: const InputDecoration(labelText: 'Color')),
                    const SizedBox(height: 16),
                    ElevatedButton.icon(onPressed: _addCar, 
                                        icon: const Icon(Icons.add), 
                                        label: const Text('Add Car')),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 16),
            // ListView for showing all cars
            Expanded(
              child: _cars.isEmpty
                  ? const Center(child: Text('No cars saved yet. Add one above!'))
                  : ListView.separated(
                      itemCount: _cars.length,
                      separatorBuilder: (_, __) =&gt; const Divider(height: 1),
                      itemBuilder: (context, index) {
                        final car = _cars[index];
                        return ListTile(
                          title: Text(car.displayName),
                          subtitle: Text('Color: ${car.color}'),
                          trailing: Wrap(
                            spacing: 8,
                            children: [
                              IconButton(onPressed: () =&gt; _editCar(car), 
                                         icon: const Icon(Icons.edit), tooltip: 'Edit'),
                              IconButton(onPressed: () =&gt; _deleteCar(car), 
                                         icon: const Icon(Icons.delete), 
                                         tooltip: 'Delete'),
                            ],
                          ),
                        );
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

// -----------------------------
// Car data model
// -----------------------------
class Car {
  const Car({
    this.id,
    required this.make,
    required this.model,
    required this.year,
    required this.color,
  });

  final int? id;
  final String make;
  final String model;
  final int year;
  final String color;

  String get displayName =&gt; '$year $make $model';

  // Copy object with optional changes
  Car copyWith({int? id, String? make, String? model, int? year, String? color}) {
    return Car(
      id: id ?? this.id,
      make: make ?? this.make,
      model: model ?? this.model,
      year: year ?? this.year,
      color: color ?? this.color,
    );
  }

  // Convert Car to Map for database storage
  Map&lt;String, Object?&gt; toMap() {
    return {'id': id, 'make': make, 'model': model, 'year': year, 'color': color};
  }

  // Rebuild Car object from Map
  factory Car.fromMap(Map&lt;String, Object?&gt; map) {
    return Car(
      id: map['id'] as int?,
      make: map['make'] as String,
      model: map['model'] as String,
      year: map['year'] as int,
      color: map['color'] as String,
    );
  }
}

// -----------------------------
// Database helper class (Singleton)
// -----------------------------
class CarDatabase {
  CarDatabase._();
  static final CarDatabase instance = CarDatabase._();

  static const _databaseName = 'cars.db';
  static const _databaseVersion = 1;
  Database? _database;

  // Singleton getter for database
  Future&lt;Database&gt; get database async {
    if (_database != null) return _database!;
    _database = await _openDatabase();
    return _database!;
  }

  // Create database and table
  Future&lt;Database&gt; _openDatabase() async {
    final directory = await getApplicationDocumentsDirectory();
    final path = p.join(directory.path, _databaseName);
    return openDatabase(
      path,
      version: _databaseVersion,
      onCreate: (db, version) async {
        await db.execute('''
          CREATE TABLE cars (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            make TEXT NOT NULL,
            model TEXT NOT NULL,
            year INTEGER NOT NULL,
            color TEXT NOT NULL
          )
        ''');
      },
    );
  }

  // -----------------------------
  // CRUD Operations
  // -----------------------------
  Future&lt;List&lt;Car&gt;&gt; fetchCars() async {
    final db = await database;
    final maps = await db.query('cars', orderBy: 'year DESC, make ASC');
    return maps.map(Car.fromMap).toList();
  }

  Future&lt;int&gt; insertCar(Car car) async {
    final db = await database;
    return db.insert('cars', car.toMap()..remove('id'));
  }

  Future&lt;int&gt; updateCar(Car car) async {
    final db = await database;
    return db.update('cars', car.toMap()..remove('id'),
        where: 'id = ?', whereArgs: [car.id]);
  }

  Future&lt;int&gt; deleteCar(int id) async {
    final db = await database;
    return db.delete('cars', where: 'id = ?', whereArgs: [id]);
  }
}

