import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';

void main() {
  runApp(const MaterialApp(home: WebViewExample()));
}

class WebViewExample extends StatefulWidget {
  const WebViewExample({super.key});

  @override
  WebViewExampleState createState() =&gt; WebViewExampleState();
}

class WebViewExampleState extends State&lt;WebViewExample&gt; {
  // The controller should be part of the State, not global
  late final WebViewController _controller;

  final FocusNode myFocusNode = FocusNode();
  final TextEditingController myTextController = TextEditingController();

  @override
  void initState() {
    super.initState();

    // Initialize the controller
    _controller = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..loadRequest(Uri.parse("https://www.google.com"));

    myTextController.text = "www.google.com";
  }

  @override
  void dispose() {
    myTextController.dispose();
    myFocusNode.dispose();
    super.dispose();
  }

  void loadUrl() {
    String rawUrl = myTextController.text.trim();

    // Basic check to avoid double https:// if user types it
    if (!rawUrl.startsWith('http')) {
      rawUrl = 'https://$rawUrl';
    }

    // Explicitly tell the controller to load the new request
    _controller.loadRequest(Uri.parse(rawUrl));

    // Dismiss keyboard
    FocusScope.of(context).unfocus();
  }

  void clearTextField() {
    myTextController.clear();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Webview URL Example')),
      // Use Column instead of ListView for a fixed header + flexible content
      body: Column(
        children: &lt;Widget&gt;[
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Row(
              children: [
                const Text('Enter Url: '),
                Expanded(
                  child: TextField(
                    controller: myTextController,
                    focusNode: myFocusNode,
                    decoration: const InputDecoration(
                      contentPadding: EdgeInsets.symmetric(horizontal: 10),
                      border: OutlineInputBorder(
                        borderSide: BorderSide(
                          color: Colors.indigo,
                          width: 2.0,
                          style: BorderStyle.solid,
                        ),
                      ),
                    ),
                    textInputAction: TextInputAction.go,
                    onSubmitted: (value) {
                      loadUrl();
                    },
                  ),
                ),
                Container(
                  margin: const EdgeInsets.only(left: 10),
                  child: ElevatedButton(
                    onPressed: clearTextField,
                    child: const Text("Clear"),
                  ),
                ),
                Container(
                  margin: const EdgeInsets.only(left: 5),
                  child: ElevatedButton(
                    onPressed: loadUrl,
                    child: const Text("Go"),
                  ),
                )
              ],
            ),
          ),
          const Divider(height: 1, thickness: 2, color: Colors.red),
          // Expanded ensures the WebView fills the rest of the screen
          Expanded(
            child: WebViewWidget(controller: _controller),
          ),
        ],
      ),
    );
  }
}
